    #[test]
    fn checks_fail_closed_and_preserve_opted_out_tests() {
        let checks = all_check_bodies();
        for needle in [
            "{{ anvil_coverage_gate_command }} {{ anvil_explicit_package_args }} run",
            "gamma run --workspace --min-score 100 --max-flaky 0 --update-hints",
        ] {
            assert!(checks.contains(needle), "checks tree missing safety behavior '{needle}'");
        }
        assert!(
            checks.contains("bolero list --profile release --target {{ quote(anvil_bolero_host_target) }} --package '{name}'"),
            "bolero discovery must use the execution profile through cargo-each"
        );
        assert!(
            checks.contains("> {{ quote(anvil_bolero_targets_file) }}"),
            "bolero discovery must truncate and replace the JSONL handoff through shell redirection"
        );
        assert!(
            checks.contains(r#"anvil_bolero_targets_file := "target" / ("bolero-list-" + just_pid() + ".jsonl")"#),
            "bolero records must use a per-Just-process file under target"
        );
        assert!(
            checks.contains("_ensure-target-dir: anvil-impact"),
            "bolero must create target only after impact calculation has had a chance to create it"
        );
        assert!(
            checks.contains(r##"if path_exists("target") { "# target directory already exists" } else { "mkdir target" }"##),
            "the target-directory helper must remain portable across the configured command shells"
        );
        assert!(
            checks.contains("each --json-lines-file {{ quote(anvil_bolero_targets_file) }} --keep-going"),
            "bolero execution must consume discovered records through cargo-each"
        );
        assert!(
            checks.contains("rm {{ quote(anvil_bolero_targets_file) }}"),
            "successful Bolero runs must remove their JSONL handoff file"
        );
        assert!(
            checks.contains(
                "bolero test --profile release --target {{ quote(anvil_bolero_host_target) }} --engine libfuzzer {{ if campaign == \"pr\""
            ),
            "bolero execution must use the profile option accepted by the pinned cargo-bolero"
        );
        assert!(
            !checks.contains("[script(\"pwsh\", \"-NoProfile\")]\nanvil-bolero:"),
            "bolero must not require a PowerShell recipe"
        );
        assert!(
            !checks.contains("bolero list @bareArgs"),
            "bolero discovery must not pass repeated --package arguments"
        );
        assert!(!checks.contains("bolero list failed; assuming no targets"));
        for needle in [
            r#"anvil_mutants_diff_dir := env("RUNNER_TEMP", env("AGENT_TEMPDIRECTORY", env("TEMP", env("TMPDIR", "."))))"#,
            r#"anvil_mutants_diff_file := anvil_mutants_diff_dir / ("anvil-mutants-diff-" + just_pid() + ".diff")"#,
            r#"trim(read(anvil_impact_input_dir + "/affected.packages")) == """#,
            "git diff --src-prefix=a/ --dst-prefix=b/ {{ quote(anvil_base_ref) }} --output={{ quote(anvil_mutants_diff_file) }}",
            "gamma run --workspace --in-diff {{ quote(anvil_mutants_diff_file) }}",
            "rm {{ quote(anvil_mutants_diff_file) }}",
        ] {
            assert!(checks.contains(needle), "mutants-diff is missing '{needle}'");
        }
        assert!(
            !checks.contains("[script(\"pwsh\", \"-NoProfile\")]\nanvil-mutants-diff:"),
            "mutants-diff must not require PowerShell"
        );
        for needle in [
            r#"anvil_readme_template := if path_exists("crates/README.j2")"#,
            r#"else if path_exists("README.j2")"#,
            "publishable and not metadata:ox-gen-readme.disable=true and (target-kind:lib or target-kind:proc-macro)",
            "target-kind:bin and not (target-kind:lib or target-kind:proc-macro)",
            "--chdir --keep-going",
            "doc2readme --lib",
            "doc2readme --bin",
        ] {
            assert!(checks.contains(needle), "readme-check is missing '{needle}'");
        }
        assert!(
            !checks.contains("[script(\"pwsh\", \"-NoProfile\")]\n_anvil-readme"),
            "readme-check must not require PowerShell"
        );
        for retired in [
            "careful-sysroot.id",
            "cargo clean",
            "[script(\"pwsh\", \"-NoProfile\")]\nanvil-careful:",
        ] {
            assert!(!checks.contains(retired), "retired careful behavior survived: {retired}");
        }
    }

