    #[cfg_attr(
        miri,
        ignore = "native and cargo-careful retain exhaustive generated-recipe contract scans; focused recipe tests preserve Miri coverage"
    )]
    #[test]
    fn every_check_matches_its_declared_impact_policy() {
        // Single source of truth for each check's impact policy. The catalog
        // encodes the policy structurally -- an `_anvil-impact-include
        // <category>` call, or its absence for unscoped checks -- and this
        // table pins the intended value. Pinning the exact category per check
        // (rather than a bare count) makes a check silently changing category,
        // or gaining/losing scoping, fail here instead of slipping through.
        let expected: BTreeMap<&str, ImpactPolicy> = EXPECTED_CHECK_POLICY.iter().copied().collect();
        assert_eq!(
            expected.len(),
            EXPECTED_CHECK_POLICY.len(),
            "EXPECTED_CHECK_POLICY contains a duplicate check entry"
        );
        let miri_runner = CHECK_HELPER_FILES
            .iter()
            .find_map(|(path, body)| path.ends_with("/miri.just").then_some(*body))
            .expect("miri.just is registered in CHECK_HELPER_FILES");

        let mut seen = BTreeSet::new();
        for (path, body) in CHECK_FILES {
            let combined_body = check_body(path, body);
            let stem = path
                .strip_prefix("justfiles/anvil/checks/")
                .and_then(|p| p.strip_suffix(".just"))
                .expect("check file path has the expected shape");
            seen.insert(stem);
            let policy = *expected
                .get(stem)
                .unwrap_or_else(|| panic!("check '{stem}' is missing from EXPECTED_CHECK_POLICY; classify it explicitly"));
            let is_miri_profile = body.contains("(_anvil-miri-test \"");
            let execution_body = if is_miri_profile { miri_runner } else { combined_body.as_str() };

            // Parse the package-file selector used by the recipe.
            let calls: Vec<&str> = ["modified", "affected", "required"]
                .into_iter()
                .filter(|cat| {
                    execution_body.contains(&format!("anvil_{cat}_selection"))
                        || execution_body.contains(&format!("{cat}.packages"))
                        || (*cat == "affected" && execution_body.contains("anvil_msrv_selection"))
                })
                .collect();
            assert!(
                calls.len() <= 1,
                "{path} makes contradictory impact-include calls {calls:?}; a check resolves exactly one category"
            );
            let depends_on_impact = execution_body
                .lines()
                .filter(|line| !line.starts_with('#') && !line.chars().next().is_some_and(char::is_whitespace))
                .filter_map(|line| line.split_once(':'))
                .any(|(_, dependencies)| dependencies.split_whitespace().any(|dependency| dependency == "anvil-impact"));

            match policy.category() {
                None => {
                    // Unscoped: no cache dependency, no include call.
                    assert!(calls.is_empty(), "{path} is declared Unscoped but consumes an impact selection");
                    assert!(!depends_on_impact, "{path} is declared Unscoped but depends on anvil-impact");
                }
                Some(category) => {
                    assert_eq!(
                        calls.as_slice(),
                        &[category],
                        "{path}: declared {policy:?} but its package-file selection is {calls:?}"
                    );
                    // A scoped check must depend on anvil-impact so the package
                    // file is fresh and delegate its consumption to cargo-each.
                    assert!(
                        depends_on_impact,
                        "{path} reads the impact cache but does not depend on anvil-impact"
                    );
                    assert!(
                        execution_body.contains(" each ")
                            || (is_miri_profile && execution_body.contains("affected.packages"))
                            || (stem == "mutants-diff" && execution_body.contains("affected.packages")),
                        "{path} must use an owned package-file consumer"
                    );
                }
            }
            assert!(
                !body.contains("ANVIL_INCLUDE_"),
                "{path} must not reference the removed ANVIL_INCLUDE_* env vars"
            );
        }

        // Bijection: every declared check exists as a file, and every file is
        // declared -- so adding or removing a check forces an explicit policy.
        let declared: BTreeSet<&str> = expected.keys().copied().collect();
        assert_eq!(
            declared, seen,
            "EXPECTED_CHECK_POLICY and the check catalog disagree on the set of checks"
        );

        // Guard the headline scoped/unscoped split so a wholesale policy shift
        // is a deliberate, reviewed edit rather than an accident.
        let scoped = EXPECTED_CHECK_POLICY.iter().filter(|(_, p)| p.category().is_some()).count();
        let unscoped = EXPECTED_CHECK_POLICY.len() - scoped;
        assert_eq!(
            (scoped, unscoped),
            (24, 7),
            "impact scoped/unscoped split changed; update EXPECTED_CHECK_POLICY deliberately"
        );
    }

    #[test]
    fn groups_just_template_includes_all_groups_and_pr_slow_groups() {
        let groups = all_group_bodies();
        for needle in [
            "anvil-pr-fast:",
            "anvil-pr-slow:",
            "anvil-pr-test:",
            "anvil-pr-msrv:",
            "anvil-pr-runtime-analysis:",
            "anvil-pr-fuzzing:",
            "anvil-pr-mutants:",
            "anvil-scheduled-test:",
            "anvil-scheduled-advisories:",
            "anvil-scheduled-exhaustive:",
        ] {
            assert!(groups.contains(needle), "groups tree missing '{needle}'");
        }
        for needle in ["anvil-pr-slow1:", "anvil-pr-slow2:", "anvil-pr-slow3:"] {
            assert!(!groups.contains(needle), "groups tree still contains stale '{needle}'");
        }
        assert!(groups.contains(
            "anvil-pr-slow: anvil-pr-slow-validate-prereqs anvil-pr-test anvil-pr-msrv anvil-pr-runtime-analysis anvil-pr-fuzzing anvil-pr-mutants"
        ));
        // PR group recipes list their own validate-prereqs aggregate first so
        // all tool checks run up front (just dedups the per-check ones).
        for needle in [
            "anvil-pr-fast: anvil-pr-fast-validate-prereqs",
            "anvil-pr-test: anvil-pr-test-validate-prereqs",
            "anvil-pr-msrv: anvil-pr-msrv-validate-prereqs",
            "anvil-pr-runtime-analysis: anvil-pr-runtime-analysis-validate-prereqs",
            "anvil-pr-fuzzing: anvil-pr-fuzzing-validate-prereqs",
            "anvil-pr-mutants: anvil-pr-mutants-validate-prereqs",
        ] {
            assert!(
                groups.contains(needle),
                "group recipe must run its validate-prereqs first: '{needle}'"
            );
        }
        // Scheduled groups are the full-workspace backstop: the public recipe
        // wraps in `_anvil-unscoped` (forcing ANVIL_IMPACT=off before the deps
        // run), and the private `_anvil-<group>` fan-out lists its
        // validate-prereqs aggregate first.
        for g in [
            "scheduled-test",
            "scheduled-advisories",
            "scheduled-runtime-analysis",
            "scheduled-exhaustive",
        ] {
            assert!(
                groups.contains(&format!("anvil-{g}: (_anvil-unscoped \"{g}\")")),
                "scheduled group {g} must wrap in _anvil-unscoped"
            );
            assert!(
                groups.contains(&format!("_anvil-{g}: anvil-{g}-validate-prereqs")),
                "scheduled group {g} private fan-out must run its validate-prereqs first"
            );
        }
    }

    #[test]
    fn impact_scoped_groups_declare_cargo_delta_prereq() {
        // Every PR group whose checks are impact-scoped depends (transitively,
        // via each scoped check) on `anvil-impact`, which invokes cargo-delta
        // when it (re)computes the impact set. The group's setup +
        // validate-prereqs must therefore install / verify cargo-delta, so a
        // missing tool fails fast at setup rather than mid-run. (pr-slow is an
        // umbrella and inherits this via pr-test / pr-msrv /
        // pr-runtime-analysis / pr-fuzzing / pr-mutants.) Scheduled groups force
        // ANVIL_IMPACT=off and never
        // recompute the impact set, so they deliberately do NOT depend on
        // cargo-delta.
        let groups = all_group_setup_bodies();
        for g in ["pr-fast", "pr-test", "pr-msrv", "pr-runtime-analysis", "pr-mutants"] {
            assert!(
                groups.contains(&format!(
                    "anvil-{g}-setup installer=\"install\": \\\n    (anvil-tool-cargo-delta-install installer)"
                )),
                "group {g} setup must install cargo-delta"
            );
            assert!(
                groups.contains(&format!(
                    "anvil-{g}-validate-prereqs: \\\n    anvil-tool-cargo-delta-validate-prereqs"
                )),
                "group {g} validate-prereqs must verify cargo-delta"
            );
        }
        assert!(groups.contains("anvil-tool-cargo-delta-install {{ installer }} anvil-bolero-setup"));
        assert!(groups.contains("anvil-tool-cargo-delta-validate-prereqs anvil-bolero-validate-prereqs"));
        // Scheduled groups force impact off and never recompute, so they must
        // NOT carry cargo-delta as a prerequisite.
        for g in [
            "scheduled-test",
            "scheduled-advisories",
            "scheduled-runtime-analysis",
            "scheduled-exhaustive",
        ] {
            assert!(
                !groups.contains(&format!(
                    "anvil-{g}-setup installer=\"install\": \\\n    (anvil-tool-cargo-delta-install installer)"
                )),
                "scheduled group {g} must not install cargo-delta (it forces ANVIL_IMPACT=off and never recomputes)"
            );
            assert!(
                !groups.contains(&format!(
                    "anvil-{g}-validate-prereqs: \\\n    anvil-tool-cargo-delta-validate-prereqs"
                )),
                "scheduled group {g} must not verify cargo-delta (it forces ANVIL_IMPACT=off and never recomputes)"
            );
        }
    }

    #[test]
    fn tiers_just_template_has_three_tiers() {
        let tiers = tier_bodies();
        for needle in ["anvil-pr:", "anvil-scheduled:", "anvil-full:", "_anvil-scheduled:", "_anvil-full:"] {
            assert!(tiers.contains(needle), "tier templates missing '{needle}'");
        }
        // Containerized execution is reached only through the explicit
        // `anvil-container` recipe, so no tier routes through a native/container
        // seam. The PR tier depends on its work directly. The scheduled and full
        // tiers are the full-workspace backstop for PR-tier impact scoping, so
        // they wrap a private `_anvil-<tier>` recipe that carries the
        // validate-prereqs aggregate (run first, so a missing tool fails up
        // front) and inherits ANVIL_IMPACT=off from the wrapper.
        assert!(!tiers.contains("_anvil-run"), "tiers must not route through an execution seam");
        for needle in [
            "anvil-pr: anvil-pr-validate-prereqs",
            "anvil-scheduled: (_anvil-unscoped \"scheduled\")",
            "_anvil-scheduled: anvil-scheduled-validate-prereqs",
            "anvil-full: (_anvil-unscoped \"full\")",
            "_anvil-full: anvil-full-validate-prereqs",
        ] {
            assert!(tiers.contains(needle), "tier wrapper missing '{needle}'");
        }
        // Scoping is disabled in the child process before its dependency graph
        // is evaluated.
        assert!(
            HELPERS_JUST.contains("--set anvil_impact_override off"),
            "the wrapper must force the internal impact override off for scheduled/full tiers"
        );
        assert!(
            HELPERS_JUST.contains("[no-exit-message]\n_anvil-unscoped"),
            "the local wrapper must preserve the child's concrete failure diagnostic"
        );
        // The scheduled tier must fan out to every scheduled group, including
        // runtime-analysis (a separate group from exhaustive).
        for needle in [
            "anvil-scheduled-test",
            "anvil-scheduled-advisories",
            "anvil-scheduled-runtime-analysis",
            "anvil-scheduled-exhaustive",
        ] {
            assert!(tiers.contains(needle), "scheduled tier must reference group '{needle}'");
        }
        // The catch-all `anvil-setup` / `anvil-validate-prereqs` must also
        // install / verify cargo-delta (the impact tool), so a local
        // `just anvil-setup` provisions a complete environment even though
        // cargo-delta isn't wired into any per-group setup.
        assert!(
            tiers.contains("anvil-setup installer=\"install\": (anvil-full-setup installer) (anvil-tool-cargo-delta-install installer)"),
            "anvil-setup must install cargo-delta"
        );
        assert!(
            tiers.contains("anvil-validate-prereqs: anvil-full-validate-prereqs anvil-tool-cargo-delta-validate-prereqs"),
            "anvil-validate-prereqs must verify cargo-delta"
        );
    }

    #[test]
    fn versions_just_has_known_tools() {
        for needle in [
            "cargo_nextest_version",
            "cargo_llvm_cov_version",
            "cargo_deny_version",
            "cargo_each_version",
            "cargo_gamma_version",
        ] {
            assert!(VERSIONS_JUST.contains(needle), "versions.just missing variable '{needle}'");
        }
    }

    #[test]
    fn stable_toolchain_selection_is_scoped_to_each_command() {
        let impact = impact_bodies();
        assert!(!VERSIONS_JUST.contains("export RUSTUP_TOOLCHAIN"));
        assert!(impact.contains("anvil_stable_toolchain_arg :="));
        assert!(impact.contains("workspace_rust_version_line := `cargo each"));
        assert!(impact.contains("quote(\"+\" + workspace_rust_version)"));
        assert!(!TOOLS_JUST.contains("_anvil-resolve-stable"));
        assert_eq!(
            TOOLS_JUST.matches("[script(\"pwsh\", \"-NoProfile\")]").count(),
            1,
            "only the cargo-spellcheck source dependency probe may require PowerShell"
        );
        assert!(TOOLS_JUST.contains("cargo each --workspace --once -- cargo "));
        assert!(TOOLS_JUST.contains("rustup component add --toolchain"));
        assert!(!TOOLS_JUST.contains("rustup target add --toolchain"));
    }

    #[cfg_attr(
        miri,
        ignore = "native and cargo-careful retain exhaustive generated-recipe contract scans; focused recipe tests preserve Miri coverage"
    )]
    #[test]
    fn setup_graph_does_not_provision_the_workspace_toolchain() {
        assert!(!TOOLS_JUST.contains("anvil-toolchain-stable-install"));
        assert!(!TOOLS_JUST.contains("rustup toolchain install '{workspace-rust-version}'"));
        assert!(
            TOOLS_JUST.contains("bolero_command_prefix"),
            "Bolero's platform gate must be a Just-time condition"
        );
        assert!(TOOLS_JUST.contains("anvil-tool-cargo-gamma-install"));
        for component in ["clippy", "rustfmt"] {
            let expected =
                format!("anvil-component-default-{component}-install installer=\"install\": (anvil-tool-cargo-each-install installer)");
            assert!(
                TOOLS_JUST.contains(&expected),
                "default component '{component}' setup must install cargo-each without selecting a workspace compiler"
            );
        }
        let checks = all_check_setup_bodies();
        for check in ["bench", "doc-build", "doc-test", "examples", "loom"] {
            let setup = format!("anvil-{check}-setup installer=\"install\": (anvil-tool-cargo-each-install installer)");
            let validation = format!("anvil-{check}-validate-prereqs: anvil-tool-rustc-validate-prereqs");
            assert!(
                checks.contains(&setup),
                "{check} setup must install cargo-each without provisioning stable"
            );
            assert!(
                checks.contains(&validation),
                "{check} validation must remain read-only prerequisite validation"
            );
        }
        assert!(TOOLS_JUST.contains("semver_matches(installed, \">=\" + minimum)"));

        let groups = all_group_setup_bodies();
        assert!(
            groups.contains("(anvil-tool-cargo-delta-install installer)") && groups.contains("(anvil-bench-setup installer)"),
            "representative group setup paths must retain tool installation"
        );
        assert!(
            TIERS_SETUP_JUST.contains("anvil-full-setup installer=\"install\":")
                && TIERS_SETUP_JUST.contains("(anvil-pr-setup installer)")
                && TIERS_SETUP_JUST.contains("anvil-setup installer=\"install\": (anvil-full-setup installer)"),
            "full and global setup must retain their transitive tool setup"
        );
    }

